1	//! Configuration and secret-file handling for the media broker.
2	//!
3	//! Write tools are opt-in: requests enable brokered adds, monitoring changes,
4	//! and search triggers, deletes enable the two-phase destructive media
5	//! removal tool, and reseeds enable the verified-complete qBittorrent reseed
6	//! into allow-listed save paths. Every upstream is optional, but at least one
7	//! must be set.
8	
9	use std::{
10	    collections::HashMap, fmt, fs, os::unix::fs::PermissionsExt, str::FromStr, time::Duration,
11	};
12	
13	use url::Url;
14	
15	/// Required broker configuration is absent or unsafe.
16	#[derive(Debug)]
17	pub struct ConfigError(String);
18	
19	impl fmt::Display for ConfigError {
20	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
21	        f.write_str(&self.0)
22	    }
23	}
24	
25	impl std::error::Error for ConfigError {}
26	
27	type Result<T> = std::result::Result<T, ConfigError>;
28	
29	macro_rules! bail {
30	    ($($message:tt)*) => { return Err(ConfigError(format!($($message)*))) };
31	}
