33	/// A credential that never appears in `Debug` output.
34	#[derive(Clone)]
35	pub struct REDACTED(String);
36	
37	impl REDACTED {
38	    pub fn new(value: impl Into<String>) -> Self {
39	        Self(value.into())
40	    }
41	
