54	/// The six allow-listed upstream APIs.
55	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
56	pub enum Service {
57	    Sonarr,
58	    Radarr,
59	    Lidarr,
60	    Tautulli,
61	    Jellyfin,
62	    Qbittorrent,
63	}
64	
65	/// One row per [`Service`], in declaration order: name, API root.
66	const SERVICES: [[&str; 2]; 6] = [
67	    ["sonarr", "/api/v3"],
68	    ["radarr", "/api/v3"],
69	    ["lidarr", "/api/v1"],
70	    ["tautulli", "/api/v2"],
71	    ["jellyfin", ""],
72	    ["qbittorrent", "/api/v2"],
73	];
74	
75	impl Service {
76	    pub const ALL: [Self; 6] = [
77	        Self::Sonarr,
78	        Self::Radarr,
79	        Self::Lidarr,
80	        Self::Tautulli,
81	        Self::Jellyfin,
82	        Self::Qbittorrent,
83	    ];
84	
85	    #[must_use]
86	    pub const fn name(self) -> &'static str {
87	        SERVICES[self as usize][0]
88	    }
89	
90	    /// The pinned API version prefix under the base URL.
91	    #[must_use]
92	    pub const fn api_root(self) -> &'static str {
93	        SERVICES[self as usize][1]
94	    }
95	
96	    /// The header that carries the API key; keys never travel in URLs.
97	    /// qBittorrent authenticates with a session cookie instead.
98	    #[must_use]
99	    pub const fn key_header(self) -> Option<&'static str> {
100	        match self {
101	            Self::Sonarr | Self::Radarr | Self::Lidarr | Self::Tautulli => Some("X-Api-Key"),
102	            Self::Jellyfin => Some("X-Emby-Token"),
103	            Self::Qbittorrent => None,
104	        }
105	    }
106	}
