108	/// How the broker authenticates to one upstream.
109	#[derive(Clone, Debug)]
110	pub enum Auth {
111	    /// A static API key sent in the service's key header.
112	    Key(REDACTED),
113	    /// `WebUI` session credentials; the broker logs in and holds the cookie.
114	    Session { username: String, password: REDACTED },
115	}
