123	/// Fully loaded settings.
124	#[derive(Clone, Debug)]
125	pub struct Settings {
126	    pub bearer_token: REDACTED,
127	    /// Indexed by `Service`; read through [`Settings::upstream`].
128	    pub upstreams: [Option<Upstream>; 6],
129	    pub allowed_hosts: Vec<String>,
130	    pub allowed_origins: Vec<String>,
131	    pub bind_host: String,
132	    pub port: u16,
133	    /// Total deadline for one upstream exchange.
134	    pub timeout: Duration,
135	    pub max_response_bytes: usize,
136	    pub enable_requests: bool,
137	    pub enable_deletes: bool,
138	    pub enable_reseeds: bool,
139	    /// Exact qBittorrent save paths a reseed may target; empty unless enabled.
140	    pub reseed_save_paths: Vec<String>,
141	    /// Lifetime of a delete confirmation.
142	    pub confirmation_ttl: Duration,
143	    /// How often a reseed polls qBittorrent while a recheck runs.
144	    pub reseed_poll_interval: Duration,
145	    /// Total time one reseed call may wait for the torrent and its recheck;
146	    /// a longer check reports `checking` and resumes on replay.
147	    pub reseed_deadline: Duration,
148	}
